package com.sdya.fund.controller;import com.sdya.fund.repository.DonationRepository;import com.sdya.fund.service.ReceiptService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller @RequiredArgsConstructor @RequestMapping("/receipts") public class ReceiptController{private final DonationRepository repo;private final ReceiptService receipt;@GetMapping("/{receiptNo}")String view(@PathVariable String receiptNo,Model m){var d=repo.findByReceiptNo(receiptNo).orElseThrow();m.addAttribute("donation",d);m.addAttribute("printText",receipt.receiptText(d));return "receipts/receipt";}}
